  /* This change has been done as part of SVF-1450 */
  max-height: calc(100vh - 216px); /* 216 = 65 (top) + 30 (margin) + 56 (header) + 65 (footer) */
  overflow-y: auto;
}

/* Added to address the issue where if we provide the same properties inside a class
(say for example overflow-y: auto for IE and FF and overflow-y: overlay for high end browsers)
the grunt is ignoring the properties and always considering the last instance (SVF-1450) */
@media screen and (-webkit-min-device-pixel-ratio: 0) {
  .cs-dialog .binf-modal-body,
  .cs-dialog .binf-modal-body > .cs-perspective-panel {
    overflow-y: overlay;
