.binf-widgets .csui-loaderpanel {
  background-color: var(--jato-background-elevation-level-4, #ffffff);
  width: 100%;
  min-width: 480px;
  max-width: 752px;
  position: relative;
  padding: var(--jato-padding-lrg, 20px) var(--jato-padding-lrg, 16px) var(--jato-padding-lrg, 20px) var(--jato-padding-xxl, 16px);
  z-index: 1045;
