  border-radius: 3px;
  min-height: 48px;
}

.csui-loaderpanel a {
  cursor: pointer;
  color: #2E3D98;
}

.csui-loaderpanel a:focus {
  outline: 1px solid #2e3d98;
  outline-offset: -1px;
}

