  z-index: 1045;
}

.binf-widgets .csui-loaderpanel .csui-loaderpanel-inner {
  vertical-align: middle;
  height: 10px;
  /* width: 140px; */
  width: auto;
  border-radius: 5px;
  background: var(--jato-background-elevation-level-0, #E1E8F6);
  position: relative;
  margin: 5px 0;
}

.binf-widgets .csui-loaderpanel .csui-loaderpanel-inner::before {
  content: "";
  width: 30%;
  height: 10px;
  border-radius: 5px;
  background: var(--jato-loader-indicator-background-neutral, #111fb0);
  border: var(--jatx-loaderpanel-loader-border-width) solid var(--jato-border-color-primary, #00000026);
  position: absolute;
  left: 0;
  animation: csui-loaderpanel-loading 4s infinite cubic-bezier(.41,.32,.4,.74);
}

@-webkit-keyframes csui-loaderpanel-loading {
  50% {
    left: 70%;
  }
}

@keyframes csui-loaderpanel-loading {
  50% {
    left: 70%;
  }
}

