}/* JATO (light, dark) theme local design-tokens for Sidepanel */
:root {
  /* Sidepanel header design-tokens */
  --jatx-sidepanel-heading-margin: 0px;
  --jatx-sidepanel-heading-font-weight: 600;
  --jatx-sidepanel-heading-letter-spacing: -0.02em;
  --jatx-sidepanel-title-margin-left: 0px;
  --jatx-sidepanel-title-padding-right: 0px;
  --jatx-sidepanel-subheading-font-size: 11px;
  --jatx-sidepanel-subheading-line-height: 14px;
  --jatx-sidepanel-subheading-margin-top: 0px;
  --jatx-sidepanel-close-icon-top: 15px;
  --jatx-sidepanel-border-width: 1px;
  /* Sidepanel body design-tokens */
  --jatx-sidepanel-body-flex: 1;
  /* Sidepanel footer design-tokens */
  --jatx-sidepanel-footer-control-margin-right: 0px;
  --jatx-sidepanel-footer-control-height: max-content;
  /* Sidepanel other design-tokens */
  --jatx-sidepanel-fadeout-content: "\00a0";
  --jatx-sidepanel-text-font-weight: 500; 
  --jatx-sidepanel-back-icon-margin-left: 0px;
}

/* Default (Carbonfiber) theme local design-tokens for Sidepanel */
[data-smart-theme="cf"] {
  /* Sidepanel header design-tokens */
  --jatx-sidepanel-heading-margin: 6px;
  --jatx-sidepanel-heading-font-weight: inherit;
  --jatx-sidepanel-heading-letter-spacing: inherit;
  --jatx-sidepanel-title-margin-left: 16px;
  --jatx-sidepanel-title-padding-right: 48px;
  --jatx-sidepanel-subheading-font-size: 12px;
  --jatx-sidepanel-subheading-line-height: 16px;
  --jatx-sidepanel-subheading-margin-top: 2px;
  --jatx-sidepanel-close-icon-top: 16px;
  --jatx-sidepanel-border-width: 0px;
  /* Sidepanel body design-tokens */
  --jatx-sidepanel-body-flex: 1 1 auto;
  /* Sidepanel footer design-tokens */
  --jatx-sidepanel-footer-control-margin-right: 24px;
  --jatx-sidepanel-footer-control-height: 48px;
  /* Sidepanel other design-tokens */
  --jatx-sidepanel-fadeout-content: none;
  --jatx-sidepanel-text-font-weight: inherit;
  --jatx-sidepanel-back-icon-margin-left: 8px;
}

/* Making scrollbar background transparent since it is taking the space of rounded corners and hiding them */
[data-smart-theme]:not([data-smart-theme="cf"]) .binf-widgets .csui-sidepanel.csui-sidepanel--from-left *::-webkit-scrollbar-track,
[data-smart-theme]:not([data-smart-theme="cf"]) .binf-widgets .csui-sidepanel.csui-sidepanel--from-left *:hover::-webkit-scrollbar-track {
